Rules.InvariantScript:
UpdateContext(
    {
        locIsVisibleLoadingCostSpinner: true,
        locCapexInitialLoadPending: true,
        locCapexInitialLoadDone: false,
        locIsVisibleSubaccountCostsDeletionDialog: false,
        locSpinnerInformationText: "",
        locIsVisibleProjectCostsMargin: false,
        locIsVisiblePopUpSpinner: false,
        locIsVisibleRightPanelSubaccountCostsEdit: false,
        locIsVisibleRightPanelSubaccountCostsDistributeEqually: false,
        locIsVisibleRightPanelEditMargin: false,
        locSelectedSubaccountCommandMode: gblAppConstants.Form.Display,
        locIsAddingStandardContract: false,
        locPanelReady: false,
        locBindGallery: false,
        locStartBinding: false,
        locIsVisibleCapexComments: false,
        locEditSaveButtonEnabled: false,
        locSelectedAccount: Blank(),
        locSelectedCostRow: Blank(),
        locScreenVisitStamp: GUID()
    }
);
// Set selected project
If(
    Not(IsBlank(Param("projectId"))),
    Set(
        gblSelectedProject,
        LookUp(
            Projects,
            Project = GUID(Param("projectId"))
        )
    ),
    Set(
        gblSelectedProject,
        LookUp(
            Projects,
            Project = GUID("33b9cc79-5b4f-f111-bec6-000d3a3855c2")
        )
    )
);
// Project start cluster number
UpdateContext(
    {
        locProjectStartClusterNo: Switch(
            Coalesce(
                gblSelectedProject.'Start Cluster',
                'Cluster States'.Greenfield
            ),
            'Cluster States'.Greenfield,
            0,
            'Cluster States'.'Cluster 1',
            1,
            'Cluster States'.'Cluster 2',
            2,
            'Cluster States'.'Cluster 3',
            3,
            'Cluster States'.'Cluster 4',
            4,
            'Cluster States'.'Cluster 5',
            5,
            'Cluster States'.'Cluster 6',
            6,
            0
        )
    }
);
// Calculate allowed cost start year/date
With(
    {
        varPreferredStartDate: If(
            locProjectStartClusterNo > 0,
            gblSelectedProject.'Acquisition date',
            gblSelectedProject.'Project Start Date'
        ),
        varFallbackStartDate: Coalesce(
            gblSelectedProject.'Acquisition date',
            gblSelectedProject.'Project Start Date',
            Today()
        )
    },
    With(
        {
            varCostStartDate: If(
                !IsBlank(varPreferredStartDate) && Year(varPreferredStartDate) > 1900,
                varPreferredStartDate,
                varFallbackStartDate
            )
        },
        UpdateContext(
            {
                locCostAllowedStartYear: If(
                    Year(varCostStartDate) > 1900,
                    Year(varCostStartDate),
                    Year(Today())
                ),
                locCostAllowedStartDate: Date(
                    If(
                        Year(varCostStartDate) > 1900,
                        Year(varCostStartDate),
                        Year(Today())
                    ),
                    1,
                    1
                )
            }
        )
    )
);
// Calculate navigation min/max year
With(
    {
        varAcquisitionYear: With(
            {d: gblSelectedProject.'Acquisition date'},
            If(
                !IsBlank(d) && Year(d) > 1900,
                Year(d),
                Blank()
            )
        ),
        varCODYear: With(
            {d: gblSelectedProject.'Operations start date (COD)'},
            If(
                !IsBlank(d) && Year(d) > 1900,
                Year(d),
                Blank()
            )
        ),
        varProjectEndYear: With(
            {d: gblSelectedProject.'End Date'},
            If(
                !IsBlank(d) && Year(d) > 1900,
                Year(d),
                Blank()
            )
        ),
        varMinClusterYear: Min(
            Filter(
                gblClusterDurations,
                !IsBlank(StartYear) && StartYear > 1900
            ),
            StartYear
        ),
        varMaxClusterYear: Max(
            Filter(
                gblClusterDurations,
                !IsBlank(EndYear) && EndYear > 1900
            ),
            EndYear
        )
    },
    UpdateContext(
        {
            locNavigationMinYear: Coalesce(
                Min(
                    Filter(
                        Table(
                            {Y: varAcquisitionYear},
                            {Y: varMinClusterYear},
                            {Y: locCostAllowedStartYear}
                        ),
                        !IsBlank(Y) && Y > 1900
                    ),
                    Y
                ),
                Year(Today())
            ),
            locNavigationMaxYear: Coalesce(
                Max(
                    Filter(
                        Table(
                            {Y: varCODYear},
                            {Y: varProjectEndYear},
                            {Y: varMaxClusterYear},
                            {
                                Y: If(
                                    gblSelectedProjectYear > 1900,
                                    gblSelectedProjectYear
                                )
                            }
                        ),
                        !IsBlank(Y) && Y > 1900
                    ),
                    Y
                ),
                Year(Today())
            )
        }
    )
);
// Build year dropdown collection
ClearCollect(
    colProjectPeriods,
    ForAll(
        Sequence(
            Max(
                locNavigationMaxYear - locNavigationMinYear + 1,
                1
            ),
            locNavigationMinYear,
            1
        ) As ProjectYearNumber,
        {
            Year: ProjectYearNumber.Value,
            Month: ForAll(
                Sequence(12) As MonthNumber,
                {
                    Name: Text(
                        Date(
                            2000,
                            MonthNumber.Value,
                            1
                        ),
                        "mmmm"
                    ),
                    Number: MonthNumber.Value
                }
            )
        }
    )
);
// Safe selected year
With(
    {
        varDefaultYear: Coalesce(
            gblSelectedProjectYear,
            locCostAllowedStartYear,
            locNavigationMinYear,
            Year(Today())
        )
    },
    Set(
        gblSelectedProjectYear,
        Min(
            Max(
                varDefaultYear,
                locNavigationMinYear
            ),
            locNavigationMaxYear
        )
    )
);
// Select real CAPEX category, not DEVEX/CAPEX Summary
UpdateContext(
    {
        locSelectedCapexAccountCategory: Coalesce(
            If(
                !IsBlank(locSelectedCapexAccountCategory.'CAPEX Account List'),
                locSelectedCapexAccountCategory
            ),
            First(
                SortByColumns(
                    Filter(
                        colCapexAccountCategoriesNew,
                        !IsBlank('CAPEX Account List') && Not(Name = "Overleveraging")
                    ),
                    "vsb_order",
                    SortOrder.Ascending
                )
            )
        ),
        locSelectedAccount: Blank(),
        locSelectedCostRow: Blank()
    }
);
// Build PCF data only if base data is ready
If(
    gblAppStarted && !IsBlank(gblSelectedProject) && !IsBlank(locSelectedCapexAccountCategory.'CAPEX Account List') && CountRows(colCapexAccountCategoriesNew) > 1 && CountRows(colCapexAccountsNew) > 0 && CountRows(colCapexSubaccountsNew) > 0,
    Reset(tab_Costs_ContentAssignableAccountCategories);
    Select(btn_Capex_Cost_Refresh_Capex_Cost_Code);
    Select(btn_Capex_Cost_Build_StandardContractOptions_Code);
    UpdateContext(
        {
            locIsVisibleLoadingCostSpinner: false,
            locCapexInitialLoadPending: false,
            locCapexInitialLoadDone: true
        }
    ),
    UpdateContext(
        {
            locIsVisibleLoadingCostSpinner: false,
            locCapexInitialLoadPending: true,
            locCapexInitialLoadDone: false
        }
    )
);

/*Concat(
    Filter(
        Table(
            {
                Show: locCostPaidByChanged,
                SortOrder: 1,
                Msg: "Are you sure you want to switch the ""Cost Paid by"" to " & Text(rad_AddContract_RightPanel_CostPaidBy_1.Selected.Value) & "? This will influence the liquidity planning and BoP"
            },
            {
                Show: locClusterLinkageChanged && CountRows(Filter(colOtherClusterHavingCost,Order<>drp_Add_Edit_Cost_Data_RightPanel_Form_Link_to_Cluster.Selected.Order)) > 0,
                SortOrder: 2,
                Msg: With(
                    {locCluster: Filter(colOtherClusterHavingCost,Order<>drp_Add_Edit_Cost_Data_RightPanel_Form_Link_to_Cluster.Selected.Order)},
                    "You have entered costs in Cluster " & Concat(
                        locCluster,
                        Order,
                        ", "
                    ) & " and linked them to " & drp_Add_Edit_Cost_Data_RightPanel_Form_Link_to_Cluster.Selected.Name & ". Would you like to proceed?"
                )
            }
        ),
        Show
    ),
    Msg,
    Char(10)&"&" & Char(10)
)*/
With(
    {
        locShowC1: locCostPaidByChanged,
        locShowC2: locClusterLinkageChanged && CountRows(
            Filter(
                colOtherClusterHavingCost,
                Order <> drp_Add_Edit_Cost_Data_RightPanel_Form_Link_to_Cluster.Selected.Order
            )
        ) > 0,
        locClusterItems: colOtherClusterHavingCost
    },
    If(
        locMilestoneRelinkResetNeeded,
        """Paid"" markers are not supported for milestone-linked costs. Linking this cost to a milestone will reset all costs to unpaid. Do you want to continue?",
        locShowC1 && locShowC2,
        "Are you sure you want to proceed with the following changes?" & Char(10) & "• Switch the ""Cost Paid By"" to " & Text(rad_AddContract_RightPanel_CostPaidBy_1.Selected.Value) & ". This will impact liquidity planning and BoP." & Char(10) & "• Costs have been entered for Clusters " & Concat(
            locClusterItems,
            Order,
            ", "
        ) & " and linked to " & drp_Add_Edit_Cost_Data_RightPanel_Form_Link_to_Cluster.Selected.Name & ".",
        locShowC1,
        "Are you sure you want to switch the ""Cost Paid by"" to " & Text(rad_AddContract_RightPanel_CostPaidBy_1.Selected.Value) & "? This will influence the liquidity planning and BoP.",
        locShowC2,
        "You have entered costs in Cluster " & Concat(
            locClusterItems,
            Order,
            ", "
        ) & " and linked them to " & drp_Add_Edit_Cost_Data_RightPanel_Form_Link_to_Cluster.Selected.Name & ". Would you like to proceed?"
    )
)

UpdateContext(
    {
        locShowClusterLinkageConfirmation: false,
        locConfirmCostPaidByChange: false,
        locConfirmClusterLinkChange: false,
        locClusterLinkageChanged: false,
        locCostPaidByChanged: false,
        locContinueToSavelinkedCluster: true
    }
);
If(
    locMilestoneRelinkResetNeeded,
   // ForAll(Filter('CAPEX Costs', Contract.'CAPEX Project Contract' = locSelectedCostRow.vsb_capexaccountlistid && 'Cost Paid' = true) As C,
