Rules.InvariantScript:
UpdateContext(
    {
        locStartCategoryBinding: false,
        locStartCategoryBinding1: false
    }
);
UpdateContext(
    {
        locSelectedAccount: Blank(),
        locSelectedCapexAccountCategory: Self.Selected,
        locIsVisibleLoadingCostSpinner: true,
        locSelectedCostRow: Blank(),
        locShowInActive: false
    }
);
If(
    IsBlank(Self.Selected.'CAPEX Account List'),
    Clear(colCapexAccountsInSelectedCategoryNew);
    Clear(colCapexSubaccountsInSelectedCategoryNew);
    Clear(colCapexContractsInSelectedCategory);
    Clear(colCapexCostsInSelectedContracts);
    ClearCollect(
        colCapexSummaryCategories,
        Filter(
            colCapexAccountCategoriesNew,
            Not(IsBlank('CAPEX Account List'))
        )
    );
    ClearCollect(
        colDevexCapexSummaryView,
        ForAll(
            colCapexSummaryCategories As Item,
            With(
                {
                    lclSubAccounts: Filter(
                        colCapexSubaccountsNew,
                        'Parent Account'.'CAPEX Account List' in Filter(
                            colCapexAccountsNew,
                            'Parent Account'.'CAPEX Account List' = Item.'CAPEX Account List'
                        ).'CAPEX Account List'
                    )
                },
                With(
                    {
                        lclContracts: Filter(
                            colCapexProjectContracts,
                            Account.'CAPEX Account List' in lclSubAccounts.'CAPEX Account List'
                        )
                    },
                    {
                        Id: Item.'CAPEX Account List',
                        Name: Item.Name,
                        Sum: Max(
                            Sum(
                                Filter(
                                    colCapexCosts,
                                    Contract.'CAPEX Project Contract' in lclContracts.'CAPEX Project Contract'
                                ),
                                Cost
                            ),
                            0
                        ),
                        ParentId: Item.'Parent Account'.'CAPEX Account List'
                    }
                )
            )
        )
    );
    UpdateContext({locIsVisibleLoadingCostSpinner: false}),
    Select(btn_Capex_Cost_Refresh_Capex_Cost_Code);
    Select(btn_Capex_Cost_Build_StandardContractOptions_Code);
    UpdateContext({locIsVisibleLoadingCostSpinner: false})
)

UpdateContext(
