    !IsBlank(Self.Selected.Year),
    UpdateContext({locIsVisibleLoadingCostSpinner: true});
    Set(
        gblSelectedProjectYear,
        Value(Self.Selected.Year)
    );
    UpdateContext({locSelectedCostRow: Blank()});
    Select(btn_Capex_Cost_Refresh_Capex_Cost_Code);
    UpdateContext({locIsVisibleLoadingCostSpinner: false})
