UpdateContext({locIsVisibleLoadingCostSpinner: true});
Set(gblSelectedProjectYear, Min(gblSelectedProjectYear + 1, locNavigationMaxYear));
UpdateContext({locSelectedCostRow: Blank()});
Select(btn_Capex_Cost_Refresh_Capex_Cost_Code);
UpdateContext({locIsVisibleLoadingCostSpinner: false})

With(
    {
        varApplicableStandardContracts: Sort(
            ShowColumns(
                Filter(
                    'Devex/Capex Standard Assumptions' As DCS,
                    DCS.Subaccount.'CAPEX Account List' = locSelectedCostRow.vsb_capexaccountlistid,
                    DCS.Country.Country = gblSelectedProject.Country.Country,
                    Lower(DCS.Technology) = Lower(gblSelectedProject.Technology),
                // Start Cluster aware filter:
// Show only standard contracts having at least one selected cluster
// greater than or equal to Project Start Cluster.
                    Or(
                        Coalesce(
                            locProjectStartClusterNo,
