Rules.InvariantScript:
ClearCollect(
    colOtherClusterHavingCost,
    With(
        {
            selOrder: drp_Add_Edit_Cost_Data_RightPanel_Form_Link_to_Cluster.Selected.Order,
            otherClusters: Filter(
                gblClusterDurations,
                Order <> drp_Add_Edit_Cost_Data_RightPanel_Form_Link_to_Cluster.Selected.Order
            )
        },
        Filter(
            otherClusters As CL,
            With(
                {
                    s: Date(
                        CL.StartYear,
                        CL.StartMonth,
                        1
                    ),
                    e: Date(
                        CL.EndYear,
                        CL.EndMonth,
                        1
                    )
                },
                !IsEmpty(
                    Filter(
                        colNewEditPanelCost As C,
                            // Any month within [s, e) has value > 0
                        (Coalesce(
                            C.JanSave,
                            0
                        ) > 0 && Date(
                            C.Year,
                            1,
                            1
                        ) >= s && Date(
                            C.Year,
                            1,
                            1
                        ) < e) || (Coalesce(
                            C.FebSave,
                            0
                        ) > 0 && Date(
                            C.Year,
                            2,
                            1
                        ) >= s && Date(
                            C.Year,
                            2,
                            1
                        ) < e) || (Coalesce(
                            C.MarSave,
                            0
                        ) > 0 && Date(
                            C.Year,
                            3,
                            1
                        ) >= s && Date(
                            C.Year,
                            3,
                            1
                        ) < e) || (Coalesce(
                            C.AprSave,
                            0
                        ) > 0 && Date(
                            C.Year,
                            4,
                            1
                        ) >= s && Date(
                            C.Year,
                            4,
                            1
                        ) < e) || (Coalesce(
                            C.MaySave,
                            0
                        ) > 0 && Date(
                            C.Year,
                            5,
                            1
                        ) >= s && Date(
                            C.Year,
                            5,
                            1
                        ) < e) || (Coalesce(
                            C.JunSave,
                            0
                        ) > 0 && Date(
                            C.Year,
                            6,
                            1
                        ) >= s && Date(
                            C.Year,
                            6,
                            1
                        ) < e) || (Coalesce(
                            C.JulSave,
                            0
                        ) > 0 && Date(
                            C.Year,
                            7,
                            1
                        ) >= s && Date(
                            C.Year,
                            7,
                            1
                        ) < e) || (Coalesce(
                            C.AugSave,
                            0
                        ) > 0 && Date(
                            C.Year,
                            8,
                            1
                        ) >= s && Date(
                            C.Year,
                            8,
                            1
                        ) < e) || (Coalesce(
                            C.SepSave,
                            0
                        ) > 0 && Date(
                            C.Year,
                            9,
                            1
                        ) >= s && Date(
                            C.Year,
                            9,
                            1
                        ) < e) || (Coalesce(
                            C.OctSave,
                            0
                        ) > 0 && Date(
                            C.Year,
                            10,
                            1
                        ) >= s && Date(
                            C.Year,
                            10,
                            1
                        ) < e) || (Coalesce(
                            C.NovSave,
                            0
                        ) > 0 && Date(
                            C.Year,
                            11,
                            1
                        ) >= s && Date(
                            C.Year,
                            11,
                            1
                        ) < e) || (Coalesce(
                            C.DecSave,
                            0
                        ) > 0 && Date(
                            C.Year,
                            12,
                            1
                        ) >= s && Date(
                            C.Year,
                            12,
                            1
                        ) < e)
                    )
                )
            )
        )
    )
);

ClearCollect(
    colOtherClusterHavingCost,
    With(
        {
            otherClusters: gblClusterDurations
            /*Filter(
                gblClusterDurations,
                Order <> drp_Add_Edit_Cost_Data_RightPanel_Form_Link_to_Cluster.Selected.Order
            )*/
        },
        Filter(
            otherClusters As CL,
            CountIf(
                colCapexCostDataToPatch As C,
                With(
                    {
                        y: Value(C.Year),
                        m: Value(C.Month),
                        sy: Value(CL.StartYear),
                        sm: Value(CL.StartMonth),
                        ey: Value(CL.EndYear),
                        em: Value(CL.EndMonth)
                    },
                    And(
                        Or(
                            y > sy,
                            And(
                                y = sy,
                                m >= sm
                            )
                        ),
                        Or(
                            y < ey,
                            And(
                                y = ey,
                                m <= em
                            )
                        )
                    )
                )
            ) > 0
        )
    )
);

